let pos = 0;

const n = input[pos++];
const lim = input[pos++];
const MOD = 1000000007n;

let A = 0;
let B = 0;

for (let i = 0; i < n; i++) {
    const fk = input[pos++];
    if (fk === 50) A++;
    else B++;
}

const c = Array.from({ length: 55 }, () => Array(55).fill(0n));
c[0][0] = 1n;

for (let i = 1; i <= 50; i++) {
    for (let j = 0; j <= i; j++) {
        const left = j > 0 ? c[i - 1][j - 1] : 0n;
        const right = j < i ? c[i - 1][j] : 0n;
        c[i][j] = (left + right) % MOD;
    }
}

const makeDP = () =>
    Array.from({ length: A + 1 }, () => Array(B + 1).fill(0n));

let previous = makeDP();
previous[A][B] = 1n;

