    const current = makeDP();
    const s = k % 2;

    for (let i = A; i >= 0; i--) {
        for (let j = B; j >= 0; j--) {
            let value = 0n;

            if (s) {
                for (let ii = i; ii <= A; ii++) {
                    let f = lim - (ii - i) * 50;

                    if (f >= 0) {
                        f = Math.floor(f / 100);
                        f = Math.min(f + j, B);

                        for (let jj = j; jj <= f; jj++) {
                            if (i !== ii || j !== jj) {
                                const ways =
                                    previous[ii][jj] *
                                    c[ii][ii - i] *
                                    c[jj][jj - j];

                                value = (value + ways) % MOD;
                            }
                        }
                    }
                }
            } else {
                for (let ii = 0; ii <= i; ii++) {
                    let f = lim - (i - ii) * 50;

                    if (f >= 0) {
                        f = Math.floor(f / 100);
                        f = Math.max(j - f, 0);

                        for (let jj = f; jj <= j; jj++) {
                            if (i !== ii || j !== jj) {
                                const ways =
                                    previous[ii][jj] *
                                    c[A - ii][i - ii] *
                                    c[B - jj][j - jj];

                                value = (value + ways) % MOD;
                            }
                        }
                    }
                }
            }

            current[i][j] = value;
        }
    }

    if (current[0][0] !== 0n) {
        console.log(`${k}\n${current[0][0].toString()}`);
        process.exit(0);
